<template><label class="filter-toggle"><span>{{ label }}</span><select :value="encoded" @change="change"><option value="">Any</option><option value="true">Yes</option><option value="false">No</option></select></label></template>
<script setup lang="ts">import { computed } from 'vue'; const props = defineProps<{ modelValue: boolean | null; label: string }>(); const emit = defineEmits<{ 'update:modelValue': [value: boolean | null] }>(); const encoded = computed(() => props.modelValue === null ? '' : String(props.modelValue)); function change(event: Event){const value=(event.target as HTMLSelectElement).value; emit('update:modelValue', value === '' ? null : value === 'true')}</script>
<style scoped>.filter-toggle{display:flex;align-items:center;justify-content:space-between;gap:.75rem}.filter-toggle span{font-size:.8rem;color:#334155}.filter-toggle select{width:82px!important}</style>
